mapper.select:
SELECT a.*
FROM activity a
WHERE a.deleted = 0


        AND a.creator_id = #{userId}


        AND EXISTS (
            SELECT 1
            FROM activity_signup s
            WHERE s.activity_id = a.id
              AND s.user_id = #{userId}
              AND s.status IN ('APPROVED', 'PROMOTED', 'COMPLETED')
              AND s.deleted = 0
        )


        AND EXISTS (
            SELECT 1
            FROM activity_waitlist w
            WHERE w.activity_id = a.id
              AND w.user_id = #{userId}
              AND w.status = 'WAITING'
              AND w.deleted = 0
        )


        AND a.end_time <= #{now}
        AND (
            a.creator_id = #{userId}
            OR EXISTS (
                SELECT 1
                FROM activity_signup s
                WHERE s.activity_id = a.id
                  AND s.user_id = #{userId}
                  AND s.status IN ('APPROVED', 'PROMOTED', 'COMPLETED')
                  AND s.deleted = 0
            )
        )


ORDER BY a.created_at DESC
